import { test, expect } from '@playwright/test';

test.describe('Error Message Accessibility for Screen Readers', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/error-page');
  });

  test('should display accessible error message when API call fails', async ({ page }) => {
    // Setup: intercept API call to simulate failure
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Intercept and verify error message is visible
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();

    // Verify error message contains appropriate text
    await expect(errorMessage).toContainText('Failed to load data');

    // Verify error message has a descriptive heading
    const errorHeading = page.getByRole('heading', { name: /data not found/i });
    await expect(errorHeading).toBeVisible();

    // Verify error message has a descriptive paragraph
    const errorDescription = page.getByText(/unable to retrieve data/i);
    await expect(errorDescription).toBeVisible();

    // Verify error message has a call-to-action button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify button is accessible to screen readers
    await expect(retryButton).toHaveAttribute('aria-label', 'Retry');

    // Verify error message has a dismiss button
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify dismiss button is accessible to screen readers
    await expect(dismissButton).toHaveAttribute('aria-label', 'Dismiss error message');
  });

  test('should display accessible error message when validation fails', async ({ page }) => {
    // Setup: intercept API call to simulate validation failure
    await page.route('**/api/validate-data', (route) => {
      route.abort('failed');
    });

    // Intercept and verify error message is visible
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();

    // Verify error message contains appropriate text
    await expect(errorMessage).toContainText('Validation failed');

    // Verify error message has a descriptive heading
    const errorHeading = page.getByRole('heading', { name: /validation error/i });
    await expect(errorHeading).toBeVisible();

    // Verify error message has a descriptive paragraph
    const errorDescription = page.getByText(/missing required fields/i);
    await expect(errorDescription).toBeVisible();

    // Verify error message has a call-to-action button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify button is accessible to screen readers
    await expect(retryButton).toHaveAttribute('aria-label', 'Retry');

    // Verify error message has a dismiss button
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify dismiss button is accessible to screen readers
    await expect(dismissButton).toHaveAttribute('aria-label', 'Dismiss validation error');
  });
});
